// web/toast.js in the stub DOM (node test, card uitoast): one severity scale, roles, the host's aria-live, the time table, the stack cap, action, dismiss.
'use strict';
const path = require('path');
const { makeDoc } = require('./nav_dom.cjs');
const T = require(path.join(process.argv[2], 'toast.cjs'));
const fails = [];
const ok = (c, m) => { if (!c) fails.push(m); };
const doc = makeDoc();
doc.N.prototype.remove = function () { if (this.parent) { this.parent.children = this.parent.children.filter((x) => x !== this); this.parent = null; } };
const timers = []; let clock = 0;
const later = (f, ms) => { const t = { f, at: clock + ms }; timers.push(t); return t; };
const clear = (t) => { const i = timers.indexOf(t); if (i >= 0) timers.splice(i, 1); };
const advance = (ms) => { clock += ms; for (const t of timers.filter((x) => x.at <= clock)) { clear(t); t.f(); } };
const S = T.create(doc, { later, clear });
ok(JSON.stringify(T.SEVERITIES) === '["info","good","warn","bad"]', 'one scale: info, good, warn, bad');
ok(T.sev('alarm') === 'bad' && T.sev('danger') === 'bad' && T.sev('ok') === 'good' && T.sev('nonsense') === 'info', 'old names map in, unknown falls to info');
const a = S.show('alarm', 'Not saved');
const host = doc.getElementById('toasts');
ok(host && host.attrs['aria-live'] === 'polite' && host.attrs.role === 'status', 'the stack is a polite live region');
ok(a.dataset.sev === 'bad' && a.attrs.role === 'alert', 'a bad toast carries data-sev bad and is announced at once (role=alert)');
const b = S.show('good', 'Saved');
ok(b.dataset.sev === 'good' && b.attrs.role === 'status', 'a good toast is a status');
advance(T.TIMES.good + 1);
ok(!host.children.includes(b) && host.children.includes(a), 'good goes at its table time, bad stays longer');
advance(T.TIMES.bad);
ok(!host.children.includes(a), 'bad goes at its table time');
let ran = 0;
const u = S.show('info', 'Deleted', { label: 'Undo', run: () => { ran++; } });
const ub = u.all().find((n) => n.tag === 'button');
ok(ub.textContent === 'Undo', 'an action toast has its own button');
ub.click(); ub.click();
ok(ran === 1 || ran === 2, 'the action ran');
ok(!host.children.includes(u), 'and the toast went');
for (let i = 0; i < 6; i++) S.show('info', 'n' + i);
ok(host.children.filter((n) => n.className === 'd-toast').length === T.MAX, 'the stack keeps at most ' + T.MAX);
const d = host.children[0].all().find((n) => n.tag === 'button'); d.click();
ok(host.children.filter((n) => n.className === 'd-toast').length === T.MAX - 1, 'Dismiss removes one');
ok(Object.values(T.TIMES).every((v) => v > 0 && v <= 30000), 'every time is in the table, under 30 s');
console.log(JSON.stringify({ fails }));
